const legacyIsland=buildIsland;buildIsland=function(n){legacyIsland(n);const p=voyagePlans[n];if(!p)return;const stone=n===6||n===7||n===8;solids=p.floors.map(([x,w,y])=>({x,w,y,h:110,kind:stone?'stone':'wood'}));ladders=[];covers=[];actors=[];objects=[];for(const [x,y,w]of p.platforms)solids.push({x,y,w,h:17,kind:stone?'stone':'wood'});for(const [x,top,bottom]of p.links){ladders.push({x,y:top,h:bottom-top});for(const y of [top,bottom])if(!solids.some(s=>s.y===y&&x>=s.x&&x<s.x+s.w))solids.push({x:x-55,y,w:110,h:17,kind:stone?'stone':'wood'});}
 for(let i=0;i<p.platforms.length;i++){const [x,y,w]=p.platforms[i];if(i%2===0){const e=enemy(x+w*.7,'pirate',4);e.y=y-84;e.origin=e.x;e.range=Math.min(100,w*.2);actors.push(e);}objects.push({type:'coin',x:x+w*.35,y:y-30});}
 for(const [x,w,y]of p.floors){for(let xx=x+200;xx<x+w-100;xx+=380){const e=enemy(xx,'pirate',4);e.y=y-84;actors.push(e);objects.push({type:'coin',x:xx-90,y:y-35});}covers.push({x:x+w*.6,y:y-65,w:85,h:65});}
 objects.push({type:'scrap',x:p.page[0],y:p.page[1]},{type:'rescue',x:p.rescue[0],y:p.rescue[1]});for(const [x,y,prop,label]of [...p.tasks].reverse())objects.unshift({type:'missionTask',prop,label,x,y});for(const [x,w,y]of p.floors)objects.push({type:'heart',x:x+w*.65,y:y-35});const boss=enemy(chapters[n].length-240,'pirate',16,true);actors.push(boss);talk(selected==='nova'?'Nova':'Sylvanas',voyages[n].brief,6);
};
function taskInteraction(o){if(o.type==='rescue'&&(chapter===6||chapter===7)&&objects.some(t=>t.type==='missionTask'&&!t.done)){talk('Objective',chapter===6?'Open the cage before freeing Gary.':'Light both braziers to free Mr. Fluffy.',3);return true;}if(o.type!=='missionTask')return false;o.done=true;if(o.prop==='bridge')solids.push({x:1720,y:300,w:1180,h:17,kind:'stone'});if(o.prop==='winch')solids.push({x:2240,y:190,w:310,h:17,kind:'wood'});effect('pickup');particles(o.x,o.y,'#e9c87e',20);talk('Objective',o.label+' · complete',3);return true;}
const standardComplete=complete;complete=function(){if(chapter>=5&&chapter<=8&&objects.some(o=>(o.type==='missionTask'||o.type==='rescue')&&!o.done)){talk('Objective','Finish the route objective and rescue your resident before returning to the tavern.',3);return;}standardComplete();};window.RumIsland.complete=complete;
function voyageHUD(){if(chapter<5||chapter>8)return;const p=voyagePlans[chapter],zone=[...p.zones].reverse().find(z=>player.x>=z[0]);$('#chapter').textContent=zone[1];const task=objects.find(o=>o.type==='missionTask'&&!o.done),rescue=objects.find(o=>o.type==='rescue'&&!o.done);$('#objective').textContent=task?task.label:rescue?'Reach the upper route · rescue '+chapters[chapter].crew:actors.some(e=>e.boss&&!e.dead)?'Defeat the captain · reach the far exit':'Return through the far exit';}
const homeMissionDetails=drawMissionDetails;drawMissionDetails=function(){homeMissionDetails();if(chapter<5||chapter>8)return;for(const o of objects)if(o.type==='missionTask'){const x=o.x-camera,y=o.y+35;if(o.prop==='brazier'){rect(x-16,y-28,32,28,'#625447');rect(x-25,y-33,50,8,'#9d8961');for(let i=0;i<6;i++){ctx.globalAlpha=o.done?.8:.2;path([[x-15+i*6,y-36],[x-10+i*5,y-70-Math.sin(clock*7+i)*12]],o.done?'#ffd07b':'#877f91',4);}ctx.globalAlpha=1;}else if(o.prop==='cage'){rect(x-45,y-130,90,130,'#1b272644');path([[x-45,y-130],[x+45,y-130],[x+45,y],[x-45,y],[x-45,y-130]],'#9c8b66',4);if(!o.done)for(let i=-30;i<=30;i+=15)path([[x+i,y-130],[x+i,y]],'#9c8b66',3);}else{ctx.strokeStyle=o.done?'#8bd1a2':'#d8b56d';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y-30,24,0,7);ctx.stroke();for(let i=0;i<4;i++){const a=i*Math.PI/2+(o.done?Math.PI/4:0);path([[x,y-30],[x+Math.cos(a)*24,y-30+Math.sin(a)*24]],ctx.strokeStyle,3);}rect(x-5,y-8,10,8,'#8e7355');}}if(chapter===6){for(const x of [1000,3650]){path([[x-camera,20],[x-60-camera,170],[x+70-camera,320]],'#5d654a',12);for(let i=0;i<5;i++)path([[x-camera+i*10,40],[x-50-camera+i*25,110]],'#71854f',3);}}if(chapter===8){const bridge=objects.find(o=>o.prop==='bridge');path([[1720-camera,300],[2900-camera,bridge.done?300:430]],'#73624e',7);for(let x=1770;x<2900;x+=100)path([[x-camera,315],[x-camera,590]],'#4c5247',3);}};
